package com.dy.artisan3d.ui.screen.main.homeimport androidx.compose.runtime.Stateimport androidx.compose.runtime.mutableStateOfimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport com.dy.artisan3d.data.AppLanguageimport com.dy.artisan3d.domain.model.Categoryimport com.dy.artisan3d.domain.repository.ArtisanMediaRepositoryimport com.dy.artisan3d.domain.repository.BrandRepositoryimport com.dy.artisan3d.domain.repository.CategoryRepositoryimport kotlinx.coroutines.asyncimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.updateimport kotlinx.coroutines.launchclass HomeViewModel(    private val repository: CategoryRepository,    private val brandRepository: BrandRepository,    private val artisanMediaRepository: ArtisanMediaRepository,    private val appLang: AppLanguage) : ViewModel() {    private val _uiState = MutableStateFlow(HomeUiState())    val uiState = _uiState.asStateFlow()    init {        fetchHomeData()    }    fun fetchHomeData(isRefresh: Boolean = false) {        // Agar allaqachon yuklangan bo'lsa va bu refresh bo'lmasa - so'rov yubormaymiz        if (!isRefresh && _uiState.value.isInitialized) return        viewModelScope.launch {            _uiState.update { it.copy(isLoading = true, isError = false) }            try {                // async orqali ikkala so'rovni parallel boshlaymiz                val categoriesDeferred = async { repository.getCategories(appLang.current) }                val brandsDeferred = async { brandRepository.getBrands(appLang.current) }                val mediaDeferred = async { artisanMediaRepository.getMediaList(1, appLang.current) }                // Ikkalasi ham tugashini kutamiz                val categories = categoriesDeferred.await()                val brands = brandsDeferred.await()                val media = mediaDeferred.await()                _uiState.update {                    it.copy(                        categories = categories,                        brands = brands,                        media = media,                        isLoading = false,                        isInitialized = true                    )                }            } catch (e: Exception) {                _uiState.update {                    it.copy(                        isLoading = false,                        isError = true,                        errorMessage = e.message ?: "Xatolik yuz berdi",                        isInitialized = true                    )                }            }        }    }}